import * as T from './three.module.js';
export function createFlightdeck(){
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(64,innerWidth/innerHeight,.03,30);camera.position.set(-.7,1.66,3.05);camera.lookAt(-.35,1.2,-3);
 scene.add(new T.HemisphereLight('#e7f2ff','#a0a5ad',2));scene.add(new T.AmbientLight('#e4ebf5',1.25));const light=new T.DirectionalLight('#fff6df',2.3);light.position.set(-4,6,-4);scene.add(light);
 const grey=new T.MeshStandardMaterial({color:'#414d5c',roughness:.78}),panel=new T.MeshStandardMaterial({color:'#596676',roughness:.72}),black=new T.MeshStandardMaterial({color:'#111923',roughness:.65}),knob=new T.MeshStandardMaterial({color:'#b4bdc2',roughness:.5}),metal=new T.MeshStandardMaterial({color:'#767e83',metalness:.6,roughness:.3});
 const cube=(w,h,d,m,x,y,z)=>{const o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);scene.add(o);return o;};
 function beam(a,b,r,m=grey){const av=new T.Vector3(...a),bv=new T.Vector3(...b),o=new T.Mesh(new T.CylinderGeometry(r,r,av.distanceTo(bv),8),m);o.position.copy(av).add(bv).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),bv.sub(av).normalize());scene.add(o);return o;}
 function label(text,w,h,x,y,z,color='#e1e5e5',background=null){const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');if(background){ctx.fillStyle=background;ctx.fillRect(0,0,512,128);}ctx.fillStyle=color;ctx.font='22px monospace';ctx.textAlign='center';ctx.fillText(text,256,72);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;const o=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:t,transparent:true}));o.position.set(x,y,z);scene.add(o);return o;}
 // Glareshield and sloping instrument panel, built as actual cabin geometry.
 cube(4.3,.9,.4,grey,0,.48,-.08);cube(4.55,.14,.9,black,0,1.04,-.18);cube(3.5,.25,.29,panel,0,1.23,-.44);
 for(const x of [-2.15,2.15]){cube(.35,.95,3.8,grey,x,.15,1.15);cube(.43,.07,3.9,black,x,.68,1.1);}
 cube(4.4,.12,4,black,0,-.38,1.1);
 beam([0,1.4,-1],[0,3,-2],.065);for(const side of [-1,1]){beam([side*2.1,.9,-.4],[side*1.6,2.95,-1.3],.11);beam([side*1.6,2.95,-1.3],[0,3,-2],.095);beam([side*2.1,.9,-.4],[side*2.35,2.7,2],.13);beam([side*2.35,2.7,2],[side*1.6,2.95,-1.3],.12);beam([0,1.4,-1],[side*2.1,1.05,-.4],.075);}
 cube(1.4,.18,2.1,grey,0,2.89,.55);const overhead=cube(1.3,.025,1.9,panel,0,2.78,.5);
 for(let j=0;j<8;j++)for(let i=0;i<6;i++){cube(.105,.035,.065,(i+j)%4===0?knob:black,-.5+i*.2,2.75,-.25+j*.21);}
 label('ENG     ELEC     FUEL     HYD',1.05,.11,0,2.72,1.5);
 // Autopilot controls, screen bezels and panel screws.
 for(const x of [-1.45,-1.02,-.35,.3,.95,1.45]){const k=new T.Mesh(new T.CylinderGeometry(.043,.047,.08,20),knob);k.rotation.x=Math.PI/2;k.position.set(x,1.19,-.25);scene.add(k);}
 for(const [text,x] of [['SPD  150',-1.16],['HDG  330',-.36],['ALT  0440',.44]])label(text,.6,.115,x,1.29,-.281,'#d9f7af','#101d19');
 for(let i=0;i<9;i++)cube(.06,.035,.02,black,-1.3+i*.32,1.11,-.28);
 const displays=[];for(const [x,name] of [[-1.35,'PFD'],[-.58,'ND'],[.27,'ENG'],[1.08,'SYS']]){cube(.73,.65,.055,black,x,.65,.15);for(const dx of [-.325,.325])for(const dy of [-.28,.28]){const screw=new T.Mesh(new T.CylinderGeometry(.012,.012,.009,8),metal);screw.rotation.x=Math.PI/2;screw.position.set(x+dx,.65+dy,.185);scene.add(screw);}const c=document.createElement('canvas');c.width=c.height=512;const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;const screen=new T.Mesh(new T.PlaneGeometry(.62,.55),new T.MeshBasicMaterial({map:t,toneMapped:false}));screen.position.set(x,.65,.186);scene.add(screen);displays.push({name,c,ctx:c.getContext('2d'),t});label(name,.3,.065,x,.29,.19);}
 // Centre pedestal with four thrust levers and two flight-management keypads.
 const pedestal=cube(.78,.48,2.05,grey,.13,-.04,1.16);for(const x of [-.03,.3]){const fms=cube(.29,.015,.4,black,x,.211,.57);for(let row=0;row<5;row++)for(let k=0;k<4;k++)cube(.045,.013,.033,knob,x-.09+k*.06,.219,.6+row*.055);}
 const levers=[];for(let i=0;i<6;i++){const x=-.15+i*.11;cube(.045,.018,.62,black,x,.21,1.27);const g=new T.Group();g.position.set(x,.23,1.25);scene.add(g);const stem=new T.Mesh(new T.BoxGeometry(.025,.27,.025),metal);stem.position.y=.13;g.add(stem);const grip=new T.Mesh(new T.BoxGeometry(.11,.07,.11),knob);grip.position.y=.28;g.add(grip);levers.push(g);}
 const thrustLabel=label('THRUST',.65,.08,.13,.16,1.96);for(let i=0;i<4;i++)cube(.035,.04,.055,knob,.41,.24,.55+i*.13);
 cube(.46,.2,.7,grey,-1.88,.78,.2);const stick=new T.Group();stick.position.set(-1.88,.9,.2);scene.add(stick);const shaft=new T.Mesh(new T.CylinderGeometry(.026,.038,.26,12),black);shaft.position.y=.12;stick.add(shaft);const grip=new T.Mesh(new T.BoxGeometry(.07,.14,.08),black);grip.position.set(0,.24,0);stick.add(grip);const red=new T.Mesh(new T.SphereGeometry(.018,8,6),new T.MeshBasicMaterial({color:'#cc3737'}));red.position.set(0,.31,.03);stick.add(red);
 const yoke=new T.Group();yoke.position.set(-1.25,.55,.35);scene.add(yoke);for(const x of [-.19,.19]){const hand=new T.Mesh(new T.BoxGeometry(.065,.22,.07),black);hand.position.set(x,.23,0);yoke.add(hand);}const bar=new T.Mesh(new T.BoxGeometry(.43,.065,.075),black);bar.position.y=.13;yoke.add(bar);const col=new T.Mesh(new T.CylinderGeometry(.045,.055,.48,16),grey);col.position.y=-.07;yoke.add(col);
 label('CAPTAIN · 1',.55,.07,-1.25,1.065,.29,'#d2d9d7');
 let last=-1;function update(state){const {speed,altitude,pitch,roll,yaw,throttle,engines,type,gear,failed=false,engineCount=type==='an225'?6:4,planeName=type==='a380'?'AIRBUS A380':type==='an225'?'ANTONOV AN-225':'BOEING 747',isAirbus=type==='a380',controlPitch=0,controlRoll=0,fuel=100,flaps=0}=state;stick.visible=isAirbus;yoke.visible=!isAirbus;stick.rotation.z=controlRoll*.22;stick.rotation.x=controlPitch*.35;yoke.rotation.z=controlRoll*.45;yoke.rotation.x=controlPitch*.32;yoke.position.y=.55-controlPitch*.04;levers.forEach((l,i)=>{l.visible=i<engineCount;l.rotation.x=-throttle*.7;});if(performance.now()-last<100)return;last=performance.now();for(const d of displays){const c=d.ctx;c.fillStyle='#070e14';c.fillRect(0,0,512,512);c.font='22px monospace';c.lineWidth=3;c.textAlign='center';
 if(d.name==='PFD'){c.save();c.beginPath();c.rect(90,70,330,335);c.clip();c.translate(256,255+pitch*450);c.rotate(-roll);c.fillStyle='#1767a0';c.fillRect(-600,-700,1200,700);c.fillStyle='#865936';c.fillRect(-600,0,1200,700);c.strokeStyle='white';for(let i=-4;i<=4;i++){c.beginPath();c.moveTo(-35,i*32);c.lineTo(35,i*32);c.stroke();}c.restore();c.strokeStyle='#fff167';c.lineWidth=5;c.beginPath();c.moveTo(150,252);c.lineTo(225,252);c.lineTo(242,263);c.moveTo(270,263);c.lineTo(287,252);c.lineTo(360,252);c.stroke();c.fillStyle='#172c38';c.fillRect(8,70,75,330);c.fillRect(429,70,75,330);c.fillStyle='white';c.font='bold 26px monospace';c.fillText(Math.round(speed),46,259);c.fillText(Math.round(altitude),466,259);c.font='18px monospace';c.fillText('KT',45,291);c.fillText('M',467,291);c.fillStyle='#78ff9f';c.fillText('THR       FD        NAV',256,32);c.fillStyle='#ffffff';c.fillText('HDG '+((Math.round(-yaw*180/Math.PI)+360)%360).toString().padStart(3,'0'),256,460);}
 else if(d.name==='ND'){c.strokeStyle='#d9e7df';for(const r of [90,180,265]){c.beginPath();c.arc(256,400,r,Math.PI,Math.PI*2);c.stroke();}c.strokeStyle='#42d99b';c.beginPath();c.moveTo(256,400);c.lineTo(275,265);c.lineTo(226,115);c.stroke();c.fillStyle='#55e7be';c.fillText('TRASA   /   NAV',256,38);c.fillStyle='white';c.fillText('N',256,92);c.fillText('W',42,382);c.fillText('E',475,382);c.fillStyle='#ffe188';c.fillText('△',256,408);c.font='18px monospace';c.fillStyle='#9cc9e1';c.fillText('GS '+Math.round(speed)+' KT',118,482);c.fillText('RNG 10',418,482);}
 else if(d.name==='ENG'){c.fillStyle='#e9f1ec';c.fillText('ENGINE / WARNING',256,37);for(let i=0,count=engineCount;i<count;i++){const x=256+(i-(count-1)/2)*(count===6?80:122);c.strokeStyle=failed&&i===0?'#ff775b':'#83eab0';c.beginPath();c.arc(x,165,engineCount===6?30:43,Math.PI*.8,Math.PI*(.8+(engines?.4+throttle:0)));c.stroke();c.fillStyle='#93efb4';c.fillText(engines&&!(failed&&i===0)?(22+throttle*70).toFixed(1):'0.0',x,235);c.fillStyle='white';c.fillText(String(i+1),x,97);}c.fillStyle='#65e890';c.fillStyle=failed?'#ff775b':'#65e890';c.fillText(failed?'ENG 1 FAULT':engines?'ENGINES RUNNING':'ENGINES OFF',256,340);c.font='18px monospace';c.fillText('MOC SILNIKÓW  '+Math.round(throttle*100)+' %',256,394);c.fillText(gear?'GEAR DOWN':'GEAR UP',256,451);}
 else{c.fillStyle='#cbd8df';c.fillText(planeName.toUpperCase(),256,45);c.strokeStyle='#96aabb';c.beginPath();c.moveTo(256,100);c.lineTo(256,350);c.moveTo(86,245);c.lineTo(256,185);c.lineTo(426,245);c.moveTo(187,336);c.lineTo(256,310);c.lineTo(325,336);c.stroke();c.fillStyle='#7ae5a0';c.font='18px monospace';c.fillText('FUEL '+Math.round(fuel)+'%   FLAPS '+flaps,256,412);c.fillText('SAMOLOCIARZE 01',256,473);}
 d.t.needsUpdate=true;}}

 function resize(aspect){const portrait=aspect<.75;camera.aspect=aspect;camera.fov=portrait?100:72;camera.position.set(-1.1,1.8,portrait?3.1:2.25);camera.lookAt(-1.1,1.6,-3);camera.updateProjectionMatrix();}return {scene,camera,update,resize};
}


